html:
{% set settings = frappe.get_cached_doc("Payment Indent Settings", "Payment Indent Settings") %}
{% set show_watermark = (settings.show_system_generated_watermark|int) == 1 %}
{% set show_qr = (settings.enable_pdf_verification_qr|int) == 1 %}
{% set watermark_text = settings.pdf_watermark_text or "SYSTEM GENERATED" %}
{% set approver_label = approver_display_label(doc.manager_approved_by) %}
{% set qr_data_uri = get_verification_qr(doc.name) if show_qr else "" %}

<style>
    @page { size: A4 landscape; margin: 10mm 8mm 12mm 8mm; }

    .pi-print {
        color: #1f2933;
        font-family: Arial, sans-serif;
        font-size: 9.5px;
        line-height: 1.35;
        position: relative;
    }
    .pi-watermark {
        position: fixed;
        top: 0; left: 0; right: 0; bottom: 0;
        z-index: -1;
        pointer-events: none;
        overflow: hidden;
    }
    .pi-watermark .row {
        color: rgba(31, 78, 121, 0.08);
        font-family: Arial, sans-serif;
        font-size: 42px;
        font-weight: 700;
        letter-spacing: 6px;
        transform: rotate(-28deg);
        transform-origin: 0 0;
        white-space: nowrap;
        margin: 38px 0;
    }
    .pi-footer {
        margin-top: 14px;
        border-top: 1px solid #cdd6e0;
        padding: 8px 4px 4px;
        background: #ffffff;
    }
    .pi-footer-title { color: #66788a; font-size: 8px; letter-spacing: .4px; text-transform: uppercase; margin-bottom: 4px; }
    .pi-footer-table { width: 100%; border-collapse: collapse; }
    .pi-footer-table td {
        vertical-align: middle;
        font-size: 8px;
        color: #465a69;
        padding: 0 6px;
    }
    .pi-footer .pi-footer-label {
        color: #8d9ba8;
        font-size: 7px;
        text-transform: uppercase;
        letter-spacing: 0.4px;
    }
    .pi-footer .pi-footer-value {
        color: #1f2933;
        font-weight: 700;
        display: block;
    }
    .pi-footer .pi-footer-token {
        font-family: "Courier New", monospace;
        font-size: 8.5px;
        word-break: break-all;
    }
    .pi-footer-qr {
        width: 100px;
        text-align: center;
    }
    .pi-footer-qr img { width: 88px; height: 88px; display: block; margin: 0 auto; }
    .pi-footer-qr .pi-footer-label { margin-top: 2px; }
    .pi-header {
        border-bottom: 2px solid #1f4e79;
        margin-bottom: 10px;
        padding-bottom: 8px;
    }
    .pi-title-row { display: table; width: 100%; }
    .pi-title-cell { display: table-cell; vertical-align: top; }
    .pi-title { color: #123b5d; font-size: 19px; font-weight: 700; margin: 0; text-transform: uppercase; }
    .pi-subtitle { color: #66788a; font-size: 10px; margin-top: 3px; }
    .pi-docbox { border: 1px solid #d8e1ea; border-radius: 4px; display: inline-block; float: right; padding: 7px 10px; min-width: 210px; background: #f7fafc; }
    .pi-docbox .label { color: #66788a; font-size: 8px; text-transform: uppercase; }
    .pi-docbox .value { color: #123b5d; font-size: 13px; font-weight: 700; }
    .pi-meta, .pi-summary, .pi-approval { width: 100%; border-collapse: collapse; margin: 8px 0; }
    .pi-meta td { border: 1px solid #e3e8ef; padding: 6px 8px; width: 25%; }
    .pi-label { color: #66788a; display: block; font-size: 8px; letter-spacing: .2px; text-transform: uppercase; }
    .pi-value { color: #1f2933; font-weight: 600; }
    .pi-summary td { border: 1px solid #d8e1ea; padding: 7px 9px; width: 25%; background: #f7fafc; }
    .pi-summary .amount { color: #123b5d; font-size: 14px; font-weight: 700; }
    .pi-section-title { color: #123b5d; font-size: 11px; font-weight: 700; margin: 11px 0 5px; text-transform: uppercase; }
    .pi-items { width: 100%; border-collapse: collapse; table-layout: fixed; }
    .pi-items th { background: #1f4e79; border: 1px solid #1b4266; color: #fff; font-size: 8px; font-weight: 700; padding: 5px 4px; text-transform: uppercase; vertical-align: middle; }
    .pi-items td { border: 1px solid #d8e1ea; padding: 5px 4px; vertical-align: top; word-wrap: break-word; }
    .pi-items tbody tr:nth-child(even) td { background: #f9fbfd; }
    .pi-right { text-align: right; }
    .pi-center { text-align: center; }
    .pi-muted { color: #66788a; }
    .pi-small { font-size: 8px; }
    .pi-status { border-radius: 3px; display: inline-block; font-size: 8px; font-weight: 700; padding: 2px 5px; text-transform: uppercase; background: #eef2f6; color: #334e68; }
    .pi-status-approved { background: #e3f8e8; color: #207544; }
    .pi-status-partially-approved { background: #fff4d6; color: #8a5a00; }
    .pi-status-rejected { background: #fde8e8; color: #a61b1b; }
    .pi-status-hold { background: #edf2ff; color: #284b8f; }
    .pi-approval td { border: 1px solid #e3e8ef; padding: 7px 8px; }
    .pi-declaration { border-left: 3px solid #1f4e79; color: #465a69; margin-top: 10px; padding: 6px 8px; background: #f7fafc; }
</style>

{% if show_watermark %}
<div class="pi-watermark">
    {% for _ in range(0, 9) %}<div class="row">{{ watermark_text }} · {{ watermark_text }} · {{ watermark_text }} · {{ watermark_text }}</div>{% endfor %}
</div>
{% endif %}

<div class="pi-print">
    {% set company = doc.items[0].company if doc.items else "" %}
    {% if company %}
        {% set letter_head = frappe.db.get_value("Company", company, "default_letter_head") %}
        {% if letter_head %}{{ frappe.render_template(frappe.db.get_value("Letter Head", letter_head, "content") or "", {"doc": doc}) }}{% endif %}
    {% endif %}

    <div class="pi-header">
        <div class="pi-title-row">
            <div class="pi-title-cell">
                <h1 class="pi-title">Payment Indent Approval Report</h1>
                <div class="pi-subtitle">Manager-level approval record. Accounting verification and payment processing are separate steps.</div>
            </div>
            <div class="pi-title-cell">
                <div class="pi-docbox">
                    <span class="pi-label">Payment Indent</span>
                    <div class="value">{{ doc.name }}</div>
                </div>
            </div>
        </div>
    </div>

    <table class="pi-meta">
        <tr>
            <td><span class="pi-label">Posting Date</span><span class="pi-value">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</span></td>
            <td><span class="pi-label">Requested By</span><span class="pi-value">{{ frappe.db.get_value("User", doc.requested_by, "full_name") or doc.requested_by }}</span></td>
            <td><span class="pi-label">Workflow State</span><span class="pi-value">{{ doc.workflow_state or "" }}</span></td>
            <td><span class="pi-label">Priority</span><span class="pi-value">{{ doc.priority or "" }}</span></td>
        </tr>
    </table>

    <table class="pi-summary">
        <tr>
            <td><span class="pi-label">Total Requested</span><span class="amount">{{ frappe.format(doc.total_requested_amount, {"fieldtype": "Currency"}) }}</span></td>
            <td><span class="pi-label">Total Approved</span><span class="amount">{{ frappe.format(doc.total_approved_amount, {"fieldtype": "Currency"}) }}</span></td>
            <td><span class="pi-label">Approved By</span><span class="pi-value">{{ approver_label }}</span></td>
            <td><span class="pi-label">Approved On</span><span class="pi-value">{{ frappe.format(doc.manager_approved_on, {"fieldtype": "Datetime"}) if doc.manager_approved_on else "" }}</span></td>
        </tr>
    </table>

    <div class="pi-section-title">Payment Lines</div>
    <table class="pi-items">
        <thead>
            <tr>
                <th style="width:3%;">Sr</th>
                <th style="width:13%;">Party</th>
                <th style="width:12%;">Company</th>
                <th style="width:9%;">Ref Type</th>
                <th style="width:10%;">Reference</th>
                <th style="width:9%;">Terms</th>
                <th style="width:9%;">Remark</th>
                <th style="width:8%;" class="pi-right">Party Balance</th>
                <th style="width:6%;">Balance</th>
                <th style="width:7%;" class="pi-right">Requested</th>
                <th style="width:7%;" class="pi-right">Approved</th>
                <th style="width:7%;">Status</th>
            </tr>
        </thead>
        <tbody>
        {% for row in doc.items %}
            {% set reference_number = row.reference_name or row.purchase_invoice or row.purchase_order or row.work_order_reference or "No Reference" %}
            {% set payment_terms = row.payment_terms_other if row.payment_terms == "Others" and row.payment_terms_other else row.payment_terms %}
            {% set status_class = (row.row_status or "Pending").lower().replace(" ", "-") %}
            <tr>
                <td class="pi-center">{{ loop.index }}</td>
                <td><strong>{{ row.party_search or row.party_name or row.party or "" }}</strong></td>
                <td>{{ row.company }}</td>
                <td>{{ row.reference_type }}</td>
                <td>{{ reference_number }}</td>
                <td>{{ payment_terms or "" }}</td>
                <td>{{ row.payment_remark or "" }}</td>
                <td class="pi-right">{{ frappe.format(row.party_balance, {"fieldtype": "Currency"}) }}</td>
                <td>{{ row.balance_type or "" }}</td>
                <td class="pi-right">{{ frappe.format(row.requested_amount, {"fieldtype": "Currency"}) }}</td>
                <td class="pi-right"><strong>{{ frappe.format(row.approved_amount, {"fieldtype": "Currency"}) }}</strong></td>
                <td><span class="pi-status pi-status-{{ status_class }}">{{ row.row_status or "" }}</span></td>
            </tr>
            {% if row.manager_remarks %}
            <tr>
                <td></td>
                <td colspan="11"><span class="pi-label">Manager Remarks</span>{{ row.manager_remarks }}</td>
            </tr>
            {% endif %}
        {% endfor %}
        </tbody>
    </table>

    <div class="pi-section-title">Approval</div>
    <table class="pi-approval">
        <tr>
            <td style="width: 33%;"><span class="pi-label">Approved By</span><span class="pi-value">{{ approver_label }}</span></td>
            <td style="width: 33%;"><span class="pi-label">Approved On</span><span class="pi-value">{{ frappe.format(doc.manager_approved_on, {"fieldtype": "Datetime"}) if doc.manager_approved_on else "" }}</span></td>
            <td style="width: 34%;"><span class="pi-label">Workflow State</span><span class="pi-value">{{ doc.workflow_state or "" }}</span></td>
        </tr>
        <tr>
            <td colspan="3"><span class="pi-label">Manager Remarks</span>{{ doc.manager_remarks or "" }}</td>
        </tr>
    </table>

    <div class="pi-declaration"><strong>Declaration:</strong> {{ doc.declaration_note or "This report confirms manager-level approval only. Accounting verification and payment processing shall be completed separately as per the institution's payment procedure." }}</div>

    <div class="pi-footer">
        <div class="pi-footer-title">Tamper Evidence &middot; Verification</div>
        <table class="pi-footer-table"><tr>
            <td style="width: 28%;">
                <span class="pi-footer-label">Document</span>
                <span class="pi-footer-value">{{ doc.name }}</span>
            </td>
            <td>
                <span class="pi-footer-label">Verification Token</span>
                <span class="pi-footer-value pi-footer-token">{{ doc.verification_token or "" }}</span>
                <span class="pi-footer-label" style="margin-top:3px;">Electronically generated through Payment Indent system. Authoritative record on RGI ERP.</span>
            </td>
            {% if qr_data_uri %}
            <td class="pi-footer-qr">
                <img src="{{ qr_data_uri }}" alt="verify" />
                <span class="pi-footer-label">Scan to verify on RGI ERP</span>
            </td>
            {% endif %}
        </tr></table>
    </div>
</div>
